query:
SELECT a.id, a.title, a.articleType, a.status, a.publicPath, a.optimizationTaskId, q.totalScore, q.blocked FROM geo_articles a LEFT JOIN geo_article_quality_scores q ON q.articleId = a.id WHERE a.projectId = 1 AND a.id IN (1,2,3) ORDER BY a.id, q.id DESC;
SELECT id, articleId, optimizationTaskId, qualityScore, publishUrl, publishStatus, needRetest, publishChannel FROM geo_publish_records WHERE projectId = 1 ORDER BY id DESC LIMIT 5;
SELECT id, taskName, status, needRetest, published_url FROM optimization_tasks WHERE projectId = 1 AND id IN (120010, 120011, 120012) ORDER BY id;

